window.kbPageData["views/entry/k-58db2e624f2d2295"] = {"key":"entry/k-58db2e624f2d2295","state":{"route":"entry/k-58db2e624f2d2295"},"node":{"id":"k-58db2e624f2d2295","mode":"k","title":"两期比重差","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["两期比重差公式","两期比重差＝现期比重×（部分增长率－整体增长率）÷（1＋部分增长率）","现期比重减去基期比重等于现期比重乘以部分与总体增速之差再除以一加部分增速","两期比重差等于现期比重乘以部分增速与整体增速之差，再除以一加部分增速","两期比重差等于现期比重减去基期比重","两期比重差等于现期比重乘以部分与整体增速之差再除以一加部分增速"],"qs":["国考 2023 地市级 行测#127","国考 2025 副省级 行测#132","国考 2025 地市级 行测#129","国考 2025 行政执法 行测#127","江苏 2023 B类 行测#123","江苏 2025 B类 行测#124","江苏 2025 C类 行测#119"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":7,"directorySummary":"两期比重差是同一统计口径下的现期比重减去基期比重。设现期比重为 s，部分量和总体量从基期到现期的增长率分别为 a 和 b，则两期比重差为 s(a−b)/(1+a)。","review":{"title":"两期比重差","type":"原理与机制","definition":"两期比重差是同一统计口径下的现期比重减去基期比重。设现期比重为 s，部分量和总体量从基期到现期的增长率分别为 a 和 b，则两期比重差为 s(a−b)/(1+a)。","explanation":"两期总体量均须大于零。根据现期量和增长率还原基期量，可得基期比重为 s(1+b)/(1+a)，其中基期部分量须大于零，且 a≠−1。在这些条件下，部分量增速高于、等于或低于总体量增速时，比重分别上升、持平或下降。比重和增长率均用小数代入，所得差乘以 100 后以百分点表示。若基期部分量大于零而现期部分量降至零，则比重下降的幅度等于基期比重。","basis":"据关联原题和解析编释。","references":[],"related":["k-b4be6d3b12f772a4","k-8a483b0a14a1001d"],"examFocus":{"国考 2023 地市级 行测#127":"用两期比重差公式判断H省实物商品网上零售额占网上零售总额的比重升降，并将变动幅度与3个百分点比较。","国考 2025 副省级 行测#132":"以业务笔数为口径，结合小额批量支付系统和清算总中心系统的同比增速，判断占比变动的方向及幅度是否达到2个百分点。","国考 2025 地市级 行测#129":"利用全国外贸进出口总额及其同比增量求整体增速，再结合东部地区的增速和现期占比判断两期比重差。","国考 2025 行政执法 行测#127":"用现期占比和两组业务笔数的同比增速还原上年同期占比，再比较两期占比的升降和百分点差。","江苏 2023 B类 行测#123":"按同一统计口径确定两年的机器人销售总额，再比较特种机器人销售额在各年所占的比重。","江苏 2025 B类 行测#124":"以核心片区过夜游客人次为部分量、全市过夜游客人次为整体量，用两期比重差判断变动幅度落在哪个区间。","江苏 2025 C类 行测#119":"分别用同比增速还原核心片区和全市上年的过夜游客人次，再用两年占比的百分点差判断区间。"}},"readings":[{"origin":"k-58db2e624f2d2295","title":"两期比重差","qs":["国考 2023 地市级 行测#127","国考 2025 副省级 行测#132"],"definition":"两期比重差是同一统计口径下的现期比重减去基期比重。设现期比重为 s，部分量和总体量从基期到现期的增长率分别为 a 和 b，则两期比重差为 s(a−b)/(1+a)。","explanation":"两期总体量均须大于零。根据现期量和增长率还原基期量，可得基期比重为 s(1+b)/(1+a)，其中基期部分量须大于零，且 a≠−1。在这些条件下，部分量增速高于、等于或低于总体量增速时，比重分别上升、持平或下降。比重和增长率均用小数代入，所得差乘以 100 后以百分点表示。若基期部分量大于零而现期部分量降至零，则比重下降的幅度等于基期比重。","evidence":"","doubt":"","references":[]},{"origin":"k-0d3d65a965cdcde5","title":"两期比重差","qs":["江苏 2025 C类 行测#119"],"definition":"两期比重差是现期比重减去基期比重，通常用百分点表示。在两期统计口径一致且相关比值有定义时，两期比重差＝现期比重×（部分量增长率－整体量增长率）÷（1＋部分量增长率）。","explanation":"将现期部分量和整体量分别除以各自的增长倍数，可还原基期比重。因此，基期比重等于现期比重乘以（1＋整体量增长率）再除以（1＋部分量增长率）。第119题中，核心片区是部分，全市是整体。现期比重为8326÷10190，代入核心片区的增长率99.9%和全市的增长率88.1%，得到比重提高约4.82个百分点，落在C项的4.5至7.3个百分点之间。","evidence":"2023年M市核心片区接待过夜游客人次占全市接待过夜游客人次的比重比上年提高的幅度：","doubt":"","references":[]},{"origin":"k-938730e99fe91d67","title":"两期比重差","qs":["国考 2025 地市级 行测#129"],"definition":"两期比重差是现期比重减去基期比重。将两期比重写成百分数时，差值用百分点表示。","explanation":"设现期比重为 p，部分和总体相对同一基期的增长率分别为 a 和 b。在基期部分量、基期总体量和现期总体量均为正时，基期比重为 p×(1+b)/(1+a)，所以两期比重差为 p×(a−b)/(1+a)，升降方向由 a−b 决定。第129题中，全国上年同期外贸进出口总额为 9.89−0.45＝9.44 万亿元，全国同比增速约为 0.45÷9.44＝4.77%，高于东部地区的 2.9%。代入东部地区的现期比重 7.75÷9.89，可得比重约下降 1.42 个百分点，选 D。","evidence":"2023年一季度，我国外贸进出口总额为9.89万亿元，同比增加0.45万亿元。","doubt":"","references":[]},{"origin":"k-b3fb7c66388d36e6","title":"两期比重差","qs":["国考 2025 行政执法 行测#127"],"definition":"在基期部分量和整体量均为正、两期整体量均为正的情况下，两期比重差（现期比重减基期比重）等于现期比重乘以（部分量增速减整体量增速），再除以（1＋部分量增速）。比重用百分数表示时，差值用百分点表示。","explanation":"基期的部分量和整体量分别等于各自的现期量除以（1＋各自的增速），因此基期比重等于现期比重乘以（1＋整体量增速）再除以（1＋部分量增速）。第127题中，小额批量支付系统的业务笔数是部分量，人民银行清算总中心系统的业务总笔数是整体量。现期比重为11.51÷54.79，约为21.01%。部分量增速5.73%高于整体量增速0.92%，代入公式得比重同比上升约0.96个百分点，选D。","evidence":"小额批量支付系统处理业务11.51亿笔，金额46.69万亿元，同比分别增长5.73%和10.03%","doubt":"","references":[]},{"origin":"k-eccffc2ef7eef94c","title":"两期比重差","qs":["江苏 2023 B类 行测#123"],"definition":"两期比重差等于现期比重减去基期比重。各期比重均用当期部分量除以当期整体量，两个百分比相减的结果用百分点表示。","explanation":"第123题的部分量是特种机器人销售额，整体量是全部机器人销售额。2021年比重为90.7÷839.0≈10.81%，2020年比重为66.5÷（422.5＋222.2＋66.5）≈9.35%。两期相减，2021年比上年提高约1.46个百分点，最接近C项的1.5个百分点。解析写作约1.4个百分点，按表中数据计算仍选C。","evidence":"2021年我国特种机器人销售额占机器人销售额的比重比上年提高","doubt":"","references":[]},{"origin":"k-efa50d12943613c2","title":"两期比重差","qs":["江苏 2025 B类 行测#124"],"definition":"两期比重差是现期比重减去基期比重。设现期部分量和整体量分别为 A、B，二者相对同一基期的增长率分别为 a、b，且两期比重均有定义，则两期比重差为 (A/B) × (a−b)/(1+a)，比重用百分数表示时，差值以百分点计。","explanation":"用现期量除以 1 加各自的增长率，可还原基期量，因此基期比重为 [A/(1+a)]/[B/(1+b)]。本题中，核心片区接待过夜游客 8326 万人次，增长 99.9%，全市接待 10190 万人次，增长 88.1%。代入得 (8326/10190) × (0.999−0.881)/(1+0.999)，即比上年提高约 4.82 个百分点，落在 C 项的 4.5 至 7.3 个百分点区间。","evidence":"核心片区接待过夜游客人次占全市接待过夜游客人次的比重比上年提高的幅度","doubt":"","references":[]}],"aspects":[{"title":"比重变动的方向和幅度","uses":[{"unit":"Q1","role":"直接考查","use":"国考 2023 地市级 行测第127题。2021年H省实物商品网上零售额同比增长10.1%，低于网上零售总额的12.5%。按现期占比和两项增速计算，比重下降约1.79个百分点，选A。","evidence":"2021年，H省实物商品网上零售额占网上零售额的比重比上年同期：","qids":["国考 2023 地市级 行测#127"]},{"unit":"Q2","role":"直接考查","use":"国考 2025 副省级 行测第132题。2023年三季度，小额批量支付系统业务笔数同比增长5.73%，高于人民银行清算总中心系统业务总笔数的0.92%。按现期占比和两项增速计算，比重上升约0.96个百分点，选D。","evidence":"2023年三季度，人民银行清算总中心系统处理支付业务中，小额批量支付系统处理业务笔数的占比同比：","qids":["国考 2025 副省级 行测#132"]}]}]},"questions":{"国考 2023 地市级 行测#127":{"paper":"国考 2023 地市级 行测","n":127,"mod":"资料分析","src":["64bc3a15d27a04e94940.pdf",27],"asrc":["f3ab652d8e31c5bbdabc.pdf",40],"card":"dd40632572b2e8da73f4953c","links":[{"id":"k-58db2e624f2d2295","role":"解题依据","why":"现期比重减基期比重等于现期比重乘以部分与整体的增速差，再除以一加部分增速。"}]},"国考 2025 副省级 行测#132":{"paper":"国考 2025 副省级 行测","n":132,"mod":"资料分析","src":["ffe12c35a46d4df574ec.pdf",27],"asrc":["ff0b352b44d417525086.pdf",41],"card":"fc9fb0f628a0cc41904be05b","links":[{"id":"k-58db2e624f2d2295","role":"解题依据","why":"设部分量和总体量的同比增速分别为 a 和 b，则现期比重减基期比重等于现期比重乘以 (a−b)/(1+a)。"}]},"国考 2025 地市级 行测#129":{"paper":"国考 2025 地市级 行测","n":129,"mod":"资料分析","src":["31f401e91aef8d11365d.pdf",27],"asrc":["8cece062c7c079b53130.pdf",41],"card":"a7526e8e7caaebc0069fccb7","links":[{"id":"k-58db2e624f2d2295","role":"解题依据","why":"该关系可以将现期份额及两个同比增速换算成份额的百分点变化。"}]},"国考 2025 行政执法 行测#127":{"paper":"国考 2025 行政执法 行测","n":127,"mod":"资料分析","src":["d8efe4e19862104d89c8.pdf",26],"asrc":["e2c4b1970d2b49eac0fd.pdf",41],"card":"65c648b04e3ed700ec565d44","links":[{"id":"k-58db2e624f2d2295","role":"解题依据","why":"部分与整体的同比增速可用于推算占比相差的百分点数。"}]},"江苏 2023 B类 行测#123":{"paper":"江苏 2023 B类 行测","n":123,"mod":"资料分析","src":["22262c34d18cd68fbee4.pdf",24],"asrc":["b08f2713d73015eac675.pdf",39],"card":"27d18fd0d3483b81965fbc7f","links":[{"id":"k-58db2e624f2d2295","role":"解题依据","why":"各期比重均为当期部分量除以整体量，两期比重的差用百分点表示。"}]},"江苏 2025 B类 行测#124":{"paper":"江苏 2025 B类 行测","n":124,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",25],"asrc":["f2ff67a0f2a2f7e8e926.pdf",41],"card":"1b083be5353fe6152a453423","links":[{"id":"k-58db2e624f2d2295","role":"直接考查","why":"材料给出现期的部分量和整体量及各自增速，可以据此求出两期比重差。"}]},"江苏 2025 C类 行测#119":{"paper":"江苏 2025 C类 行测","n":119,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",24],"asrc":["d1de3b437151c05b769e.pdf",36],"card":"03c471d7e233eb659516e3da","links":[{"id":"k-58db2e624f2d2295","role":"直接考查","why":"材料提供现期部分量、整体量及两者增长率，可据此求两期比重差。"}]}},"terms":{"k-b4be6d3b12f772a4":{"id":"k-b4be6d3b12f772a4","mode":"k","type":"原理与机制","title":"同一总体下的比重差","qs":[],"count":2,"basisGroup":"部分量和总体量","review":true},"k-8a483b0a14a1001d":{"id":"k-8a483b0a14a1001d","mode":"k","type":"原理与机制","title":"由比重还原部分量","qs":[],"count":2,"basisGroup":"部分量和总体量","review":true}},"references":{},"topics":[],"units":{"k-58db2e624f2d2295":[["国考 2023 地市级 行测#127"],["国考 2025 副省级 行测#132"],["国考 2025 地市级 行测#129"],["国考 2025 行政执法 行测#127"],["江苏 2023 B类 行测#123"],["江苏 2025 B类 行测#124"],["江苏 2025 C类 行测#119"]]}};
